CREATE TABLE public.career_intentions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, content jsonb NOT NULL DEFAULT '{}'::jsonb, onboarding_step integer NOT NULL DEFAULT 0, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.career_intentions TO authenticated; GRANT ALL ON public.career_intentions TO service_role;
ALTER TABLE public.career_intentions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Candidate owns intentions" ON public.career_intentions FOR ALL TO authenticated USING (user_id = auth.uid() AND public.has_role(auth.uid(), 'candidate')) WITH CHECK (user_id = auth.uid() AND public.has_role(auth.uid(), 'candidate'));
CREATE INDEX career_intentions_owner ON public.career_intentions(user_id, updated_at DESC);
CREATE TABLE public.career_journeys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL DEFAULT 'My 30-day career journey', start_date date NOT NULL, archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.career_journeys TO authenticated; GRANT ALL ON public.career_journeys TO service_role;
ALTER TABLE public.career_journeys ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Candidate owns journeys" ON public.career_journeys FOR ALL TO authenticated USING (user_id = auth.uid() AND public.has_role(auth.uid(), 'candidate')) WITH CHECK (user_id = auth.uid() AND public.has_role(auth.uid(), 'candidate'));
CREATE UNIQUE INDEX one_active_career_journey ON public.career_journeys(user_id) WHERE archived_at IS NULL;
CREATE TABLE public.career_action_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, journey_id uuid NOT NULL, name text NOT NULL, description text NOT NULL DEFAULT '', week integer NOT NULL DEFAULT 1 CHECK (week BETWEEN 1 AND 4), due_date date NOT NULL, category text NOT NULL DEFAULT 'career', completed_at timestamptz, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(journey_id,user_id) REFERENCES public.career_journeys(id,user_id) ON DELETE CASCADE);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.career_action_tasks TO authenticated; GRANT ALL ON public.career_action_tasks TO service_role;
ALTER TABLE public.career_action_tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Candidate owns tasks" ON public.career_action_tasks FOR ALL TO authenticated USING (user_id = auth.uid() AND public.has_role(auth.uid(), 'candidate')) WITH CHECK (user_id = auth.uid() AND public.has_role(auth.uid(), 'candidate'));
CREATE INDEX career_tasks_journey ON public.career_action_tasks(user_id,journey_id,due_date);
CREATE TABLE public.career_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN ('vision','board_settings','affirmation','affirmation_completion','journal','routine','reflection','coaching','milestone','activity')), content jsonb NOT NULL DEFAULT '{}'::jsonb, event_date date NOT NULL DEFAULT CURRENT_DATE, dedup_key text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,kind,dedup_key));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.career_records TO authenticated; GRANT ALL ON public.career_records TO service_role;
ALTER TABLE public.career_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Candidate owns private career records" ON public.career_records FOR ALL TO authenticated USING (user_id = auth.uid() AND public.has_role(auth.uid(), 'candidate')) WITH CHECK (user_id = auth.uid() AND public.has_role(auth.uid(), 'candidate'));
CREATE INDEX career_records_owner_kind ON public.career_records(user_id,kind,event_date DESC);
COMMENT ON TABLE public.career_records IS 'Validated typed private entities for vision board items/settings, affirmations/completions, journals/reflections, routines, coaching history, milestones and explicitly recorded activity; never recruiter-visible.';
CREATE TABLE public.job_applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, resume_id uuid REFERENCES public.resumes(id) ON DELETE SET NULL, resume_title text NOT NULL DEFAULT '', role text NOT NULL, company text NOT NULL, url text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'Preparing' CHECK(status IN ('Preparing','Applied','Screening','Interview','Offer','Closed')), applied_at timestamptz, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.job_applications TO authenticated; GRANT ALL ON public.job_applications TO service_role;
ALTER TABLE public.job_applications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Candidate owns applications" ON public.job_applications FOR ALL TO authenticated USING(user_id = auth.uid() AND public.has_role(auth.uid(),'candidate')) WITH CHECK(user_id = auth.uid() AND public.has_role(auth.uid(),'candidate') AND (resume_id IS NULL OR EXISTS (SELECT 1 FROM public.resumes r WHERE r.id = resume_id AND r.user_id = auth.uid())));
CREATE INDEX job_applications_owner ON public.job_applications(user_id,updated_at DESC);
CREATE OR REPLACE FUNCTION public.start_career_journey(journey_title text, journey_start date, task_rows jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ DECLARE new_id uuid; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'candidate') THEN RAISE EXCEPTION 'Unauthorized'; END IF; PERFORM 1 FROM public.profiles WHERE id=auth.uid() FOR UPDATE; UPDATE public.career_journeys SET archived_at=now() WHERE user_id=auth.uid() AND archived_at IS NULL; INSERT INTO public.career_journeys(user_id,title,start_date) VALUES(auth.uid(),journey_title,journey_start) RETURNING id INTO new_id; INSERT INTO public.career_action_tasks(user_id,journey_id,name,description,week,due_date,category) SELECT auth.uid(),new_id,t.name,t.description,t.week,t.due_date,t.category FROM jsonb_to_recordset(task_rows) AS t(name text,description text,week integer,due_date date,category text); RETURN new_id; END; $$;
REVOKE ALL ON FUNCTION public.start_career_journey(text,date,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.start_career_journey(text,date,jsonb) TO authenticated;
